BEGIN;
INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'basic', 'multiple_choice', 'What is ''fabric shrinkage'' testing (e.g., wash shrinkage %) meant to assess before a fabric goes into garment production?', '["How much the fabric''s dimensions (length/width) change after washing, so garment patterns can be adjusted (oversized) to compensate and the finished garment fits correctly after the customer''s first wash","The exact color fastness of the fabric, unrelated to dimensional change","The fabric''s resistance to tearing under mechanical stress","The fiber content percentage of a blended fabric"]'::jsonb, 'How much the fabric''s dimensions (length/width) change after washing, so garment patterns can be adjusted (oversized) to compensate and the finished garment fits correctly after the customer''s first wash', 'Shrinkage testing measures dimensional change after standardized washing; garment pattern makers use this data to size cutting patterns slightly larger than the target finished size, compensating for expected shrinkage so the garment fits correctly after the customer eventually washes it.', 1, '{"shrinkage-testing"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'Why would a fabric with HIGH, unpredictable shrinkage be especially problematic for a garment with multiple different fabric panels (e.g., body fabric plus a contrast trim fabric)?', '["If different panels shrink at different, unpredictable rates, the finished garment can pucker, twist, or become mismatched in size at the seams after washing","Shrinkage differences between panels have no visible or functional effect on a finished garment","High shrinkage always affects every fabric panel by the exact same amount, causing no relative distortion","This scenario only matters for single-panel garments, not multi-fabric garments"]'::jsonb, 'If different panels shrink at different, unpredictable rates, the finished garment can pucker, twist, or become mismatched in size at the seams after washing', 'When different fabrics (with different fiber content, construction, or finishing) are combined in one garment, mismatched shrinkage rates between panels can cause seam puckering, panel size mismatch, or garment distortion after washing — a common quality risk multi-fabric garment designs specifically need to test and control for.', 2, '{"shrinkage-mismatch"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'basic', 'multiple_choice', 'What does ''crease recovery'' (wrinkle recovery angle) testing measure for a fabric?', '["How well a fabric recovers its original flat shape after being folded/creased under controlled conditions","The fabric''s exact final color depth after dyeing","The fabric''s total weight per square meter","The fiber diameter of yarn used in the fabric"]'::jsonb, 'How well a fabric recovers its original flat shape after being folded/creased under controlled conditions', 'Crease recovery testing folds a fabric sample under a standard load for a set time, then measures the angle it recovers to after release — a higher recovery angle indicates better wrinkle resistance/recovery, an important comfort/appearance property especially for garments meant to look neat without ironing.', 1, '{"crease-recovery"}'::text[]);
COMMIT;
